mapper.select:
select historical.tradeDate as buyDate, historical.shareAmt as buyHolding, historical.issuer, decode(historical.yield,NULL,historical.yieRuleId,historical.yield) as mYield, decode(historical.assetId,NULL,historical.setId,historical.assetId) AS assetId, historical.assetName as assetAbbr, historical.type12 as assetTypeFiveName from ( select tpd.TRADE_DATE as tradeDate, fp.FINPROD_MARKET_ID as assetId, fp.FINPROD_ABBR as assetName, tpd.TRADE_ID as tradeId, tpd.SHARE_AMT as shareAmt, tpd.YIELD as yield, fci.CASH_ID as cashId, fccr.EFF_DATE as effDate, fccr.YIELD as yieRuleId, fpt.TYPE_12 as type12, ftp.FINPROD_ID as setId, case when fp.MDATE is not null then MONTHS_BETWEEN(fp.MDATE,tpd.TRADE_DATE) else MONTHS_BETWEEN(ftp.MDATE,tpd.TRADE_DATE) end as lastPeriod, fp.ISSUER as issuer from TRD_PRODUCT_DEAL tpd left join FIN_PRODUCT fp on tpd.FINPROD_ID = fp.FINPROD_ID left join FIN_TRADE_PRODUCT ftp on ftp.FINPROD_ID = tpd.FINPROD_ID and ftp.BRANCH = tpd.BRANCH left join FIN_PRODUCT_TYPE fpt on tpd.FINPROD_ID = fpt.FINPROD_ID and tpd.BRANCH = fpt.BRANCH left join FIN_CASH_INFO fci on tpd.FINPROD_ID = fci.FINPROD_ID and tpd.BRANCH = fci.BRANCH and fci.CASH_TYPE_2 = 'C02' left join FIN_CASH_CALC_RULE fccr on fci.CASH_ID = fccr.CASH_ID and fccr.EFF_DATE <= tpd.TRADE_DATE where tpd.PS = 'T01' and tpd.TOTLE_TRADE_ID is null and tpd.TRADE_STATUS='01' and tpd.IS_CANCEL='N'
and tpd.TRADE_DATE >= to_date(#{startCheckDate}, 'yyyy-MM-dd')
and tpd.TRADE_DATE <= to_date(#{endCheckDate}, 'yyyy-MM-dd')
and fpt.TYPE_10 IN
#{item}
and fpt.TYPE_10 IN
#{item}
and fpt.TYPE_11 IN
#{item}
and fpt.TYPE_12 IN
#{item}
) historical left join MST_CUSTOMER_INFO_ADD mcia on mcia.CUSTOMER_ID = historical.issuer where historical.effDate =(select max(EFF_DATE) from FIN_RATE_INFO fri where fri.CASH_ID = historical.cashId)
and historical.lastPeriod >= #{lastMinPeriod}
and historical.lastPeriod <= #{lastMaxPeriod}
and mcia.PARTY_TYPE2 = #{partyType}
